    @pytest.mark.parametrize("format_param", ["json", "geo+json", "xml", "raw"])
    def test_get_gairmet_success_different_formats(self, api_client, format_param):
        """Test successful GET request with different format parameters"""
        params = {"format": format_param}
        response = api_client.get("/api/data/gairmet", params=params)
        
        assert response.status_code == 200
        assert response.headers['content-type'] is not None
        
        if format_param == "json":
            assert "application/json" in response.headers['content-type']
            data = response.json()
            assert isinstance(data, list)
        elif format_param == "geo+json":
            assert "application/geo+json" in response.headers['content-type']
            data = response.json()
            assert "type" in data
            assert "features" in data
        elif format_param == "xml":
            assert "application/xml" in response.headers['content-type']
        else:  # raw
            assert "text/plain" in response.headers['content-type']
    
